(function () {
  "use strict";

  // Solid 3D wireframe letters for the home hero's easter egg and the account ID on the settings
  // page. The shapes are glyph outlines (assets/js/wire-font-outlines.js, generated by
  // scripts/build-wire-font.py) that the script has made angular: every curve is cut down to a few
  // straight facets (an O is an octagon) and the letters lean slightly forward, so the face is
  // KANASAKA's own, chamfered like the logo. Each letter is then extruded: its outline is drawn at
  // the front and again at the back, joined at every corner. A loop with fewer than two corners
  // gets an edge at its left and right extremes (the silhouette it shows when it turns) so it
  // does not float apart; set LOOP_ANCHORS to false for none.
  //
  //   KanasakaWireFont.layout(lines)  -> { items: [{ ch, x }], width, height }   (grid units)
  //   KanasakaWireFont.solid(lines, { halfDepth }) -> { edges, width, height }
  //     edges: [x0, y0, z0, x1, y1, z1], in grid units centred on (0, 0), letter height 6, ordered
  //     letter by letter so a build-on reads left to right. Lower case is drawn as upper case.

  var data = window.KanasakaWireFontData;
  if (!data) return;

  var GLYPH_HEIGHT = 6; // a capital is 6 grid units high
  var LINE_HEIGHT = 9; // 6 plus a gap of 3
  var SPACE = 3;
  var LOOP_ANCHORS = true;
  var SCALE = GLYPH_HEIGHT / data.cap;

  function advanceOf(ch) {
    var glyph = data.glyphs[ch];
    return glyph ? glyph[0] * SCALE : SPACE;
  }

  function lineWidth(line) {
    var w = 0;
    for (var i = 0; i < line.length; i += 1) w += advanceOf(line[i]);
    return w;
  }

  function normalise(lines) {
    return lines.map(function (line) {
      return String(line).toUpperCase();
    });
  }

  // Where each letter of each line sits: x is the left of its advance, y the top of its line.
  function layout(lines) {
    var rows = normalise(lines);
    var widest = Math.max.apply(null, rows.map(lineWidth).concat([1]));
    var height = (rows.length - 1) * LINE_HEIGHT + GLYPH_HEIGHT;
    var items = [];
    rows.forEach(function (line, row) {
      var x = -lineWidth(line) / 2;
      for (var i = 0; i < line.length; i += 1) {
        if (data.glyphs[line[i]]) items.push({ ch: line[i], x: x, y: -height / 2 + row * LINE_HEIGHT });
        x += advanceOf(line[i]);
      }
    });
    return { items: items, width: widest, height: height };
  }

  function solid(lines, options) {
    var hd = (options && options.halfDepth) || 0.6;
    var block = layout(lines);
    var edges = [];

    block.items.forEach(function (item) {
      var glyph = data.glyphs[item.ch][1];
      var loops = glyph.map(function (contour) {
        var flat = contour[0];
        var pts = [];
        for (var i = 0; i < flat.length; i += 2) {
          // font units are y-up with the baseline at 0: flip to y-down grid units
          pts.push([item.x + flat[i] * SCALE, item.y + (data.cap - flat[i + 1]) * SCALE]);
        }
        var marks = contour[1];
        if (!LOOP_ANCHORS && marks.length < 2) marks = [];
        return { pts: pts, marks: marks };
      });

      [hd, -hd].forEach(function (z) {
        loops.forEach(function (loop) {
          var n = loop.pts.length;
          for (var i = 0; i < n; i += 1) {
            var a = loop.pts[i];
            var b = loop.pts[(i + 1) % n];
            edges.push([a[0], a[1], z, b[0], b[1], z]);
          }
        });
      });
      loops.forEach(function (loop) {
        loop.marks.forEach(function (k) {
          var p = loop.pts[k];
          edges.push([p[0], p[1], hd, p[0], p[1], -hd]);
        });
      });
    });

    return { edges: edges, width: block.width, height: block.height };
  }

  window.KanasakaWireFont = { glyphs: data.glyphs, layout: layout, solid: solid };
})();
